CREATE TABLE companies(id TEXT PRIMARY KEY, name TEXT NOT NULL, settings_json TEXT NOT NULL DEFAULT '{}');
INSERT INTO companies(id,name) VALUES('smerch','Smerch');
CREATE TABLE customers(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, email TEXT NOT NULL, data_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(company_id,id));
CREATE TABLE users(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('administrator','sales','production','accountant','customer')), customer_id TEXT REFERENCES customers(id), enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE records(namespace TEXT NOT NULL,id TEXT NOT NULL,payload TEXT NOT NULL,version INTEGER NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(namespace,id));
CREATE TABLE products(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),name TEXT NOT NULL,data_json TEXT NOT NULL,UNIQUE(company_id,id));
CREATE TABLE variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),sku TEXT NOT NULL,attributes_json TEXT NOT NULL,UNIQUE(product_id,sku));
CREATE TABLE prices(id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES variants(id),minimum_quantity INTEGER NOT NULL CHECK(minimum_quantity>0),unit_minor INTEGER NOT NULL CHECK(unit_minor>=0),currency TEXT NOT NULL CHECK(currency='DKK'),valid_at TEXT NOT NULL);
CREATE TABLE quotes(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),customer_id TEXT NOT NULL REFERENCES customers(id),status TEXT NOT NULL CHECK(status IN ('draft','sent','accepted','rejected','converted')),snapshot_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,accepted_at TEXT,order_id TEXT UNIQUE);
CREATE TABLE orders(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),customer_id TEXT REFERENCES customers(id),source TEXT NOT NULL,source_id TEXT UNIQUE,order_status TEXT NOT NULL,payment_status TEXT NOT NULL,production_status TEXT NOT NULL,delivery_status TEXT NOT NULL,snapshot_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,paid_at TEXT,invoice_number TEXT,invoice_registered_at TEXT,invoice_registered_by TEXT REFERENCES users(id),UNIQUE(company_id,id));
CREATE TABLE order_lines(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),position INTEGER NOT NULL,product_id TEXT REFERENCES products(id),variant_id TEXT REFERENCES variants(id),sku TEXT NOT NULL,description TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),net_minor INTEGER CHECK(net_minor>=0),vat_minor INTEGER CHECK(vat_minor>=0),snapshot_json TEXT NOT NULL,UNIQUE(order_id,position));
CREATE TABLE files(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),order_id TEXT NOT NULL REFERENCES orders(id),version INTEGER NOT NULL,name TEXT NOT NULL,mime_type TEXT NOT NULL,sha256 TEXT NOT NULL,bytes BLOB NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE proofs(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),file_id TEXT NOT NULL REFERENCES files(id),version INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','published','approved','changes')),customer_id TEXT REFERENCES customers(id),decision_at TEXT,decision_by TEXT REFERENCES users(id),comment TEXT,UNIQUE(order_id,version));
CREATE TABLE production(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),approved_proof_id TEXT REFERENCES proofs(id),deadline TEXT,status TEXT NOT NULL CHECK(status IN ('waiting','ready','in_progress','completed')),specification TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE shipments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),shipped_at TEXT NOT NULL,carrier TEXT,tracking_url TEXT,tracking_number TEXT,created_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE shipment_lines(shipment_id TEXT NOT NULL REFERENCES shipments(id),order_line_id TEXT NOT NULL REFERENCES order_lines(id),quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(shipment_id,order_line_id));
CREATE TABLE documents(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),order_id TEXT NOT NULL REFERENCES orders(id),type TEXT NOT NULL CHECK(type IN ('basis','shipment','receipt')),version INTEGER NOT NULL,snapshot_json TEXT NOT NULL,pdf BLOB,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(order_id,type,version));
CREATE TABLE jobs(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),kind TEXT NOT NULL,aggregate_id TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','running','done','failed','uncertain')),attempts INTEGER NOT NULL DEFAULT 0,available_at INTEGER NOT NULL,locked_at INTEGER,error_code TEXT,created_at TEXT NOT NULL,UNIQUE(kind,aggregate_id));
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id TEXT NOT NULL REFERENCES companies(id),actor_id TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,at TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE requests(company_id TEXT NOT NULL REFERENCES companies(id),actor_id TEXT NOT NULL,key TEXT NOT NULL,operation TEXT NOT NULL,input_hash TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(company_id,actor_id,key));
CREATE TABLE messages(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),audience TEXT NOT NULL CHECK(audience IN ('internal','customer','accountant','production')),subject TEXT NOT NULL,text TEXT NOT NULL,recipient TEXT,status TEXT NOT NULL CHECK(status IN ('note','queued','sending','sent','uncertain','failed')),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE INDEX orders_company_created ON orders(company_id,created_at);
CREATE INDEX jobs_pending ON jobs(status,available_at);
CREATE INDEX audit_entity ON audit(entity_type,entity_id,at);
CREATE INDEX files_order ON files(order_id,version);
